const raw = String($input.item.json.content?.[0]?.text ?? '');
const match = raw.match(/\{[\s\S]*\}/);
const cleaned = match ? match[0] : raw.trim();

const ALLOWED_CATEGORIES = [
  "medication_supply_issue", "titration_dose_query", "safeguarding_concern",
  "clinical_deterioration_report", "appointment_scheduling", "assessment_status_enquiry",
  "shared_care_gp_coordination", "complaint_service_dispute", "billing_payment_issue",
  "new_patient_sales_enquiry", "general_information_request"
];
const ALWAYS_ESCALATE = [
  "titration_dose_query", "safeguarding_concern",
  "clinical_deterioration_report", "complaint_service_dispute"
];

let parsed;
let parseError = false;
try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  parseError = true;
  parsed = {};
}

const categoryWasInvalid = !ALLOWED_CATEGORIES.includes(parsed.primary_category);
const category = categoryWasInvalid ? "general_information_request" : parsed.primary_category;
const riskSignals = Array.isArray(parsed.risk_signals) ? parsed.risk_signals : [];
const confidence = parsed.confidence ?? "low";

let action, decisionReason;
if (parseError) {
  action = "escalate"; decisionReason = "LLM response could not be parsed as JSON";
} else if (categoryWasInvalid) {
  action = "escalate"; decisionReason = "Model returned a category outside the fixed taxonomy";
} else if (riskSignals.length > 0) {
  action = "escalate"; decisionReason = `Risk signal(s) present: ${riskSignals.join(", ")}`;
} else if (ALWAYS_ESCALATE.includes(category)) {
  action = "escalate"; decisionReason = `Category "${category}" always routes to human review`;
} else if (confidence === "low") {
  action = "escalate"; decisionReason = "Model confidence was low";
} else {
  action = "auto_resolve"; decisionReason = "No risk signals, category not sensitive, confidence acceptable";
}

// Airtable's single-select options use its own exact display strings.
// Keep "action" lowercase for the Switch node's logic; use "action_label" for Airtable writes.
// IMPORTANT: these two strings must match Airtable's option text EXACTLY —
// including case, spacing, and hyphenation — or the write will be rejected.
const ACTION_LABELS = {
  auto_resolve: "Auto-resolve",
  escalate: "Escalate"
};
const actionLabel = ACTION_LABELS[action];

// Explicit reference to the trigger node — do not rely on these passing through automatically.
// Airtable nests real columns under .fields; the record's own Airtable ID sits at the top level as .id.
const trigger = $('Airtable Trigger').item.json;

const noteText = `Ticket ${trigger.fields['Ticket ID']} — Halcyon Health Triage
Category: ${category}
Risk signals: ${riskSignals.join(", ") || "none"}
Confidence: ${confidence}
Urgency: ${parsed.urgency ?? "medium"}
Sentiment: ${parsed.sentiment ?? "n/a"}
Reasoning: ${parsed.reasoning ?? "n/a"}
Action taken: ${action} (${decisionReason})
Suggested reply: ${parsed.suggested_reply ?? "n/a"}`;

return {
  json: {
    airtable_record_id: trigger.id,
    ticket_id: trigger.fields['Ticket ID'],
    sender_email: trigger.fields['Sender Email'],
    original_message: trigger.fields['Message'],
    primary_category: category,
    risk_signals: riskSignals,
    risk_signals_text: riskSignals.join(", "),
    confidence,
    urgency: parsed.urgency ?? "medium",
    sentiment: parsed.sentiment ?? null,
    reasoning: parsed.reasoning ?? null,
    suggested_reply: parsed.suggested_reply ?? null,
    action,
    action_label: actionLabel,
    decision_reason: decisionReason,
    parse_error: parseError,
    status: action === "auto_resolve" ? "Auto-Resolved" : "Escalated",
    timestamp: new Date().toISOString(),
    note_text: noteText
  }
};

